const motion=document.createElement('button');motion.className='motion-control';motion.textContent='Pause motion';motion.setAttribute('aria-pressed','false');const motionItem=document.createElement('li');motionItem.append(motion);document.querySelector('.footer-menu').append(motionItem);let paused=false;function setMotion(value){paused=value;document.documentElement.classList.toggle('no-motion',value);motion.textContent=value?'Enable motion':'Pause motion';motion.setAttribute('aria-pressed',String(value));if(value){window.ScrollSmoother?.get()?.kill();window.ScrollTrigger?.getAll().forEach(t=>{t.animation?.progress(1);t.kill()});window.gsap?.globalTimeline.getChildren().forEach(t=>{if(t.repeat?.()===-1)t.pause();else t.progress?.(1)});}else location.reload();}motion.addEventListener('click',()=>setMotion(!paused));if(matchMedia('(prefers-reduced-motion: reduce)').matches)setMotion(true);
// Preserve Creovibe's accordion behaviour while making the triggers keyboard-accessible.
document.querySelectorAll('.acc-btn').forEach((button,i)=>{button.setAttribute('role','button');button.tabIndex=0;const panel=button.nextElementSibling;if(panel){panel.id='faq-answer-'+i;button.setAttribute('aria-controls',panel.id);}button.setAttribute('aria-expanded',String(button.classList.contains('active')));button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();button.click();}});button.addEventListener('click',()=>setTimeout(()=>document.querySelectorAll('.acc-btn').forEach(b=>b.setAttribute('aria-expanded',String(b.classList.contains('active')))),0));});
// Complete the template's mobile navigation with keyboard/focus support.
const mobileNav=document.querySelector('.mobile-menu');
const menuButtons=[...document.querySelectorAll('.mobile-nav-toggler')];
let menuReturnFocus=null;
function syncMenu(){const open=document.body.classList.contains('mobile-menu-visible');menuButtons.forEach(b=>b.setAttribute('aria-expanded',String(open)));mobileNav.inert=!open;mobileNav.setAttribute('aria-hidden',String(!open));}
syncMenu();
new MutationObserver(syncMenu).observe(document.body,{attributes:true,attributeFilter:['class']});
menuButtons.forEach(button=>button.addEventListener('click',()=>{menuReturnFocus=button;syncMenu();setTimeout(()=>{if(document.body.classList.contains('mobile-menu-visible'))mobileNav.querySelector('.close-btn').focus({preventScroll:true});},paused?0:650);}));
function closeMobileMenu(){document.body.classList.remove('mobile-menu-visible');syncMenu();menuReturnFocus?.focus();}
mobileNav.querySelector('.close-btn').addEventListener('click',closeMobileMenu);
document.addEventListener('keydown',event=>{if(!document.body.classList.contains('mobile-menu-visible'))return;if(event.key==='Escape'){event.preventDefault();closeMobileMenu();}if(event.key==='Tab'){const items=[...mobileNav.querySelectorAll('a[href],button')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
